/* MarginDesk local MVP. All writes stay in this browser's localStorage. */
(()=>{
'use strict';
const KEY='margindesk-local-v1';
const clone=x=>JSON.parse(JSON.stringify(x));
const MarginEngine=window.MarginEngine;
const seed=clone(window.SEED_DATA);
let generatedLegacySnapshots=false;
let model=(()=>{try{const raw=localStorage.getItem(KEY);if(!raw)return seed;const saved=JSON.parse(raw),hasSnapshots=Array.isArray(saved.marginSnapshots);generatedLegacySnapshots=!hasSnapshots;return {...seed,...saved,company:seed.company,users:seed.users,marginPolicy:{...seed.marginPolicy,...(saved.marginPolicy||{})},marginSnapshots:hasSnapshots?saved.marginSnapshots:MarginEngine.buildMonthlySnapshots(saved.orders||seed.orders,saved.customers||seed.customers,saved.products||seed.products,seed.company.id)}}catch(e){return seed}})();
const removedLegacyTrendData=[...(model.customers||[]),...(model.products||[])].some(row=>Object.prototype.hasOwnProperty.call(row,'priorMargin'));
[...(model.customers||[]),...(model.products||[])].forEach(row=>{delete row.priorMargin});
if(removedLegacyTrendData||generatedLegacySnapshots){try{localStorage.setItem(KEY,JSON.stringify(model))}catch(e){}}
let page='dashboard',pricePreview=null,vendorReview=null,pricePage=1,priceFilter='',quoteDraft={customerId:'c-acme',lines:[{productId:'p-v100',qty:5,discountPct:8,rebatePct:1,accessory:0}]},quoteFocus=false,collapsed=localStorage.getItem('md-sidebar-collapsed')==='1',inflationDraft={category:'Steel Valves',change:6,text:'Steel +6%'},policyScope='global';
const root=document.getElementById('viewRoot'),nav=[...document.querySelectorAll('[data-page]')],$=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v??'').trim().toLowerCase().replace(/\s+/g,' ');
const money=n=>Number.isFinite(Number(n))?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n)):'—';
const num=v=>Number.isFinite(Number(v))?Number(v):0;
const pct=n=>`${Number(n||0).toFixed(1)}%`;
const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
const customer=id=>model.customers.find(x=>x.id===id);
const product=id=>model.products.find(x=>x.id===id);
const activeRole=()=>localStorage.getItem('margindesk-role')||'owner';
function save(){try{localStorage.setItem(KEY,JSON.stringify(model))}catch(e){toast('Could not save local changes. Your browser storage may be full.')}}
function toast(message){const t=$('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3600)}
function showModal(content){$('modal').innerHTML=content;$('modalBack').classList.add('show')}
function closeModal(){$('modalBack').classList.remove('show');$('modal').replaceChildren()}
$('modalBack').addEventListener('click',e=>{if(e.target===$('modalBack'))closeModal()});
function policyFor(c,p){const over=model.marginPolicy.overrides||{};return over.category?.[p?.category]||over.tier?.[c?.tier]||model.marginPolicy}
function scopedPolicy(){if(policyScope==='global')return model.marginPolicy;const [kind,key]=policyScope.split('|');model.marginPolicy.overrides||={category:{},tier:{}};model.marginPolicy.overrides[kind]||={};if(!model.marginPolicy.overrides[kind][key])model.marginPolicy.overrides[kind][key]={target:model.marginPolicy.target,floor:model.marginPolicy.floor,walkAway:model.marginPolicy.walkAway};return model.marginPolicy.overrides[kind][key]}
function zoneOf(marginRate,policy=model.marginPolicy){return MarginEngine.classify(marginRate,policy)}
function zoneLabel(z,rate,policy){if(z==='green')return'Green · auto-approved';if(z==='red')return`Red · blocked below ${policy.walkAway}% walk-away`;return rate<policy.floor?`Yellow · manager review, below ${policy.floor}% floor`:'Yellow · manager approval'}
function labelClass(z){return z==='green'?'success':z==='red'?'blocked':'pending'}
function tierPrice(p,c){return MarginEngine.priceFor(p,c)}
function calcOrder(o){const c=customer(o.customerId),p=product(o.productId);return c&&p?MarginEngine.calculateOrder(o,c,p):null}
function quoteMath(lines=quoteDraft.lines,c=customer(quoteDraft.customerId)){return MarginEngine.calculateQuote(lines,c,model.products)}
function allOrders(){return model.orders.map(calcOrder).filter(Boolean)}
function currentPeriodMargin(){const orders=allOrders(),months=[...new Set(orders.map(x=>x.order.month).filter(Boolean))].sort(),month=months.at(-1)||'',currentOrders=orders.filter(x=>x.order.month===month),current=MarginEngine.aggregate(currentOrders),trend=MarginEngine.trendFor(model.marginSnapshots,'company',model.company.id);return{current:current.rate,month,trend,orders:currentOrders}}
function marginTrendHtml(entityType,entityId){const trend=MarginEngine.trendFor(model.marginSnapshots,entityType,entityId);if(trend.status==='insufficient')return '<span class="small muted">Not enough history</span>';return `<span class="trend ${trend.direction==='up'?'up':'down'}">${trend.direction==='up'?'↑':'↓'} ${Math.abs(trend.delta).toFixed(1)} pts vs ${esc(trend.previous.month)}</span>`}
function marginAlerts(){return allOrders().filter(o=>o.margin<0).map(o=>({id:`margin-${o.order.id}`,level:'urgent',message:`${o.order.id} · ${o.c.name} is below zero pocket margin.`,orderId:o.order.id}))}
function setPage(p){page=p;nav.forEach(b=>b.classList.toggle('active',b.dataset.page===p));render()}
nav.forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
function pageHead(title,desc,right=''){return`<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${right?`<span class="chip gray">${right}</span>`:''}</div>`}
function metric(label,value,trend=null){const trendHtml=!trend?'':trend.status==='insufficient'?'<span class="small muted">Not enough history</span>':`<span class="trend ${trend.direction==='up'?'up':'down'}">${trend.direction==='up'?'↑':'↓'} ${Math.abs(trend.delta).toFixed(1)} pts vs ${esc(trend.previous.month)}</span>`;return`<div class="metric"><span>${label}</span><strong>${value}</strong>${trendHtml}</div>`}
function render(){ $('roleSelect').innerHTML=model.users.map(u=>`<option value="${esc(u.role)}" ${activeRole()===u.role?'selected':''}>${esc(u.name)} · ${esc(u.role)}</option>`).join('');root.innerHTML=page==='dashboard'?dashboardHtml():page==='prices'?pricesHtml():page==='quoting'?quoteHtml():page==='rebates'?rebatesHtml():connectorsHtml();renderSidebar();if(page==='prices'&&pricePreview)drawPricePreview();if(page==='quoting')drawQuoteTotals();if(page==='rebates')drawRebateAudit();syncNav()}
function syncNav(){nav.forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelectorAll('.bottom-nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page))}
$('roleSelect').addEventListener('change',e=>{localStorage.setItem('margindesk-role',e.target.value);toast(`Switched to ${e.target.options[e.target.selectedIndex].text}`);render()});
function dashboardHtml(){const p=currentPeriodMargin(),orders=allOrders(),alertList=[...(model.alerts||[]).filter(a=>a.level!=='urgent'),...marginAlerts()],urgent=alertList.filter(a=>a.level==='urgent'),gaps=orders.filter(o=>o.margin<0),total=orders.reduce((s,o)=>s+o.list,0),zones=model.quotes.filter(q=>q.status==='Open').map(q=>{const pr=product(q.productId),cu=customer(q.customerId);const m=quoteMath([{productId:q.productId,qty:q.qty,discountPct:q.discountPct,rebatePct:q.rebatePct||0,accessory:q.accessory||0}],cu);return zoneOf(m.rate,policyFor(cu,pr))});const counts={green:zones.filter(x=>x==='green').length,yellow:zones.filter(x=>x==='yellow').length,red:zones.filter(x=>x==='red').length};const w=MarginEngine.aggregate(orders);const steps=[['List price',w.list,'list'],['Discounts',-w.discount,'discount'],['Off-invoice rebates',-w.rebate,'rebate'],['Freight',-w.freight,'freight'],['Payment terms',-w.terms,'terms'],['Pocket price',w.pocket,'pocket'],['Pocket margin',w.margin,'margin']];const max=Math.max(...steps.map(s=>Math.abs(s[1])),1);const leakGroups=new Map();orders.forEach(o=>{const key=o.c.name+' · '+o.p.category;const g=leakGroups.get(key)||{name:key,customer:o.c,product:o.p,loss:0,orders:0,region:o.c.region};g.loss+=o.discount+o.rebate+o.freight+o.terms;g.orders++;leakGroups.set(key,g)});const leaks=[...leakGroups.values()].sort((a,b)=>b.loss-a.loss).slice(0,5);const approval=model.approvals.filter(a=>a.status==='Pending');return`${pageHead('Dashboard','See which deals are protecting margin, where margin is leaking, and what needs your attention.','Manager workspace')}
${urgent.length?`<div class="alert-banner"><div><strong>${urgent.length} urgent margin leakage alert${urgent.length===1?'':'s'}</strong><div class="small">${esc(urgent[0].message)}</div></div><button class="primary" data-action="fix-now">Fix Now</button></div>`:''}
<div class="grid-4" style="margin-bottom:14px">${metric('Net sales · sample period',money(total))}${metric('Pocket margin · weighted',pct(p.current),p.trend)}${metric('Orders below zero margin',String(gaps.length))}${metric('Open quotes by guardrail',`${counts.green} / ${counts.yellow} / ${counts.red}`)}</div>
<div class="card"><div class="card-head"><h2>Pocket-margin waterfall</h2><span class="small muted">Click any step to inspect the exact orders and accounts behind it.</span></div><div class="waterfall">${steps.map(([name,val,key])=>`<button class="water-step ${val<0?'loss':''} ${key==='pocket'||key==='margin'?'final':''}" data-water="${key}"><small>${name}</small><strong>${money(val)}</strong><div class="bar-track"><i style="width:${Math.max(5,Math.abs(val)/max*100)}%"></i></div></button>`).join('')}</div><div class="callout">Pocket price = list price − discounts − off-invoice rebates − freight − payment-terms cost. Pocket margin = pocket price − COGS.</div></div>
<div class="grid-2"><section class="card"><div class="card-head"><h2>Top margin leak generators</h2><button data-action="matrix">View Profitability Matrix</button></div>${leaks.map(g=>`<div class="leak-row"><div><b>${esc(g.name)}</b><div class="small muted">${g.orders} orders · ${esc(g.region)} region · ${esc(g.product.sku)}</div></div><div class="leak-impact">${money(g.loss)}</div><button data-search-customer="${esc(g.customer.id)}">View</button></div>`).join('')}</section>
<section class="card"><div class="card-head"><h2>Order risk checks</h2><span class="chip ${gaps.length?'red':'success'}">${gaps.length} loss-making</span></div>${gaps.length?gaps.map(o=>`<div class="leak-row"><div><b>${esc(o.order.id)} · ${esc(o.c.name)}</b><div class="small muted">${esc(o.p.sku)} · freight ${money(o.freight/o.qty)} / unit · ${o.order.discountPct}% discount</div></div><div class="leak-impact">${money(o.margin)}</div><button data-order="${esc(o.order.id)}">Review</button></div>`).join(''):`<div class="empty">No loss-making orders in this sample.</div>`}</section></div>
<section class="card"><div class="card-head"><h2>Guardrail control panel</h2><span class="small muted">Green auto-approves · Yellow routes for manager approval · Red is locked.</span></div>${policyPanelHtml()}</section>
${approvalQueueHtml(approval)}
<section class="card"><div class="card-head"><h2>Connect your current data</h2><button data-action="connectors">View connectors</button></div><div class="grid-3">${connectorCardsSmall()}</div><div class="small muted" style="margin-top:9px">Use realistic seeded data now; import CSVs locally. Live API sync is planned and not connected in this prototype.</div></section>`}
function policyPanelHtml(){const m=scopedPolicy(),role=activeRole(),openQuotes=model.quotes.filter(q=>q.status==='Open'),zones=openQuotes.map(q=>{const c=customer(q.customerId),p=product(q.productId),math=quoteMath(q.lines||[{productId:q.productId,qty:q.qty,discountPct:q.discountPct,rebatePct:q.rebatePct||0,accessory:q.accessory||0}],c);return zoneOf(math.rate,policyFor(c,p))}),counts={green:zones.filter(z=>z==='green').length,yellow:zones.filter(z=>z==='yellow').length,red:zones.filter(z=>z==='red').length},scopeOptions=[['global','Global defaults'],...new Set(model.products.map(p=>p.category)).values()].map(x=>Array.isArray(x)?x:[`category|${x}`,`Category · ${x}`]);model.customers.forEach(c=>{if(!scopeOptions.some(x=>x[0]===`tier|${c.tier}`))scopeOptions.push([`tier|${c.tier}`,`Customer tier · ${c.tier}`])});return`<div class="toolbar" style="margin-bottom:12px"><label for="policyScope" class="small muted">Apply rules to</label><select id="policyScope" class="input" ${role==='rep'?'disabled':''}>${scopeOptions.map(([v,l])=>`<option value="${esc(v)}" ${policyScope===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div class="policy-grid">${[['target','Target margin',35],['floor','Manager floor',30],['walkAway','Walk-away margin',25]].map(([k,label,max])=>`<div class="policy-box"><label>${label}<strong id="policy-${k}-label">${m[k]}%</strong></label><input type="range" min="5" max="${max}" value="${m[k]}" step="1" data-policy="${k}" ${role==='rep'?'disabled':''}><div class="small muted">${k==='target'?'At or above target can quote automatically.':k==='floor'?'Below this, show a higher-risk Yellow label to managers.':'Below this, block quote generation.'}</div></div>`).join('')}</div><div class="callout" id="openQuotePreview" style="margin-top:12px">Live preview · ${openQuotes.length} open quotes: ${counts.green} Green · ${counts.yellow} Yellow · ${counts.red} Red. Counts update when the rules change.</div><div class="zone-preview"><div class="green-zone"><b>GREEN · AUTO APPROVED</b><br>≥ ${m.target}%</div><div class="yellow-zone"><b>YELLOW · MANAGER APPROVAL</b><br>${m.walkAway}% to ${m.target-1}%</div><div class="red-zone"><b>RED · HARD LOCK</b><br>&lt; ${m.walkAway}%</div></div><div class="small muted" style="margin-top:9px">Category or customer-tier thresholds can differ from the global defaults. Below the manager floor remains Yellow and needs explicit review; below Walk-away is blocked.</div>`}
function approvalQueueHtml(list){if(activeRole()==='rep')return`<section class="card"><div class="card-head"><h2>My approval requests</h2><span class="small muted">Status updates in this workspace.</span></div>${myApprovalsHtml()}</section>`;return`<section class="card"><div class="card-head"><h2>Approval inbox</h2><span class="chip ${list.length?'yellow':'gray'}">${list.length} pending</span></div>${list.length?list.map(a=>{const q=a.quote||model.quotes.find(x=>x.id===a.quoteId),c=customer(q?.customerId),p=product(q?.productId),math=q?quoteMath(q.lines||[{productId:q.productId,qty:q.qty,discountPct:q.discountPct,rebatePct:q.rebatePct||0,accessory:q.accessory||0}],c):null;return`<div class="approval-card"><div class="toolbar" style="justify-content:space-between"><b>${esc(q?.id||a.quoteId)} · ${esc(c?.name||'Customer')}</b><span class="chip yellow">${pct(math?.rate)} margin · ${money(math?.margin)}</span></div><div class="small muted">${esc(p?.sku||'Multi-line quote')} · requested by ${esc(a.requestedBy||'Sales rep')}</div><div class="row-actions" style="margin-top:10px"><button class="danger" data-approval="${esc(a.id)}" data-decision="Denied">Deny</button><button class="primary" data-approval="${esc(a.id)}" data-decision="Approved">Approve</button></div></div>`}).join(''):`<div class="empty">No quotes are waiting for your review.</div>`}</section>`}
function myApprovalsHtml(){const list=model.approvals.filter(a=>a.requestedByRole==='rep');if(!list.length)return'<div class="empty">No approval requests yet. Yellow quotes will appear here.</div>';return list.map(a=>`<div class="version-row"><span><b>${esc(a.quoteId)}</b> · ${esc(a.status)}</span><span class="chip ${a.status==='Pending'?'yellow':a.status==='Approved'?'':'red'}">${esc(a.status)}</span></div>`).join('')}
function orderDetailHtml(key){const orders=allOrders();let list=orders;if(key==='discount')list=orders.filter(x=>x.discount>0);else if(key==='rebate')list=orders.filter(x=>x.rebate>0);else if(key==='freight')list=orders.filter(x=>x.freight>0);else if(key==='terms')list=orders.filter(x=>x.terms>0);else if(key==='margin')list=orders.filter(x=>x.margin<0);const labels={list:'Orders contributing list price',discount:'Orders with discounts',rebate:'Orders with off-invoice rebates',freight:'Orders with freight charges',terms:'Orders with payment-term costs',pocket:'Orders after pocket-price deductions',margin:'Orders with negative pocket margin'};return`<h2>${labels[key]||'Order details'}</h2><p class="muted small">Source order and account rows behind this waterfall step.</p><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Order</th><th>Customer</th><th>SKU</th><th>Qty</th><th>Amount</th><th>Margin</th><th>Rate</th></tr></thead><tbody>${list.map(o=>{const val=key==='list'?o.list:key==='discount'?o.discount:key==='rebate'?o.rebate:key==='freight'?o.freight:key==='terms'?o.terms:key==='pocket'?o.pocket:o.margin;return`<tr><td>${esc(o.order.id)}</td><td>${esc(o.c.name)}</td><td>${esc(o.p.sku)}</td><td>${o.qty}</td><td>${money(val)}</td><td>${money(o.margin)}</td><td>${pct(o.rate)}</td></tr>`}).join('')}</tbody></table></div><div class="modal-foot"><button data-close>Close</button></div>`}
function pricesHtml(){const role=activeRole();return`${pageHead('Price Lists','Upload a supplier or customer price file, review every row, compare it with the current catalog, and publish only after approval.','Manager and analyst workspace')}
<section class="card"><div class="card-head"><h2>Update a price list</h2><span class="small muted">CSV files · local browser processing</span></div><div class="dropzone" id="priceDrop"><b>Drop a CSV price file here</b><div class="muted small" style="margin:5px">or choose a file from your computer</div><button data-action="choose-price">Choose CSV file</button><input id="priceFile" class="hidden" type="file" accept=".csv,text/csv,.txt"></div><div class="callout">Use a CSV export from Excel. This local prototype does not parse binary .xlsx workbooks; export the sheet as CSV first. You can download an Excel-compatible CSV below, edit it in Excel, then upload it to sync.</div><div id="priceErrors"></div><div id="pricePreview"></div><div class="row-actions" style="margin-top:12px"><button data-action="export-prices">Export to Excel (CSV)</button><button data-action="sync-prices">Upload to Sync</button>${role==='rep'?'<span class="chip yellow">Rep view · publishing disabled</span>':'<button class="primary" data-action="commit-prices" id="commitPrices" disabled>Commit reviewed changes</button>'}</div></section>
${vendorReviewHtml()}<div class="grid-2"><section class="card"><div class="card-head"><h2>Current price list</h2><span class="small muted">${model.products.length.toLocaleString()} SKUs</span></div><input id="priceFilter" class="input" placeholder="Filter SKU, product, category…" value="${esc(priceFilter)}"><div id="productTable" style="margin-top:10px">${productTableHtml()}</div></section><section class="card"><div class="card-head"><h2>Version history</h2><button data-action="undo-price" ${canUndo()?'':'disabled'}>Undo latest</button></div>${(model.priceVersions||[]).slice().reverse().map(v=>`<div class="version-row"><span><b>${esc(v.label)}</b><div class="small muted">${new Date(v.createdAt).toLocaleString()}</div></span><span class="chip gray">${v.count} SKU${v.count===1?'':'s'}</span></div>`).join('')}</section></div>`}
function vendorReviewHtml(){const suppliers=[...new Set(model.products.map(p=>p.supplier).filter(Boolean))];return `<section class="card"><div class="card-head"><div><h2>Supplier cost review</h2><div class="small muted">Compare a supplier CSV with the catalog. Flag 25%+ cost increases, unit mismatches, duplicate and new items, and optionally missing SKUs.</div></div><span class="chip gray">Review before export</span></div><div class="grid-2"><div class="field"><label for="vendorSupplier">Supplier in this file</label><input id="vendorSupplier" class="input" list="vendorSupplierChoices" value="${esc(vendorReview?.supplier||'')}" placeholder="e.g. NorthStar Metals"><datalist id="vendorSupplierChoices">${suppliers.map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist></div><label class="toolbar small"><input type="checkbox" id="vendorFullCatalog" ${vendorReview?.fullCatalog?'checked':''}> This file is the supplier’s full catalog; flag missing SKUs as possibly discontinued.</label></div><div class="dropzone" id="vendorDrop" style="margin-top:12px"><b>Drop a supplier cost CSV here</b><div class="muted small" style="margin:5px">Required: SKU and unit cost. Optional: name and unit of measure.</div><button data-action="choose-vendor-file">Choose CSV file</button><input id="vendorFile" class="hidden" type="file" accept=".csv,text/csv,.txt"></div><div id="vendorReviewResult" style="margin-top:12px">${vendorReview?drawVendorReview():`<div class="empty">No supplier file loaded. Start with the sample file to see the review format.</div>`}</div><div class="row-actions" style="margin-top:10px"><button data-action="download-vendor-sample">Download sample supplier CSV</button><button data-action="clear-vendor-review" ${vendorReview?'':'disabled'}>Clear review</button><button class="primary" data-action="export-vendor-approved" ${vendorReview?.rows?.some(r=>r.approved&&!r.duplicate)?'':'disabled'}>Export approved changes</button></div></section>`}
function drawVendorReview(){if(!vendorReview)return '';const rows=vendorReview.rows||[],missing=vendorReview.missing||[],counts={spike:rows.filter(r=>r.spike).length,unit:rows.filter(r=>r.unitMismatch).length,duplicate:rows.filter(r=>r.duplicate).length,new:rows.filter(r=>r.isNew).length};return `<div class="toolbar"><span class="chip orange">${counts.spike} cost spikes ≥25%</span><span class="chip orange">${counts.unit} unit mismatches</span><span class="chip orange">${counts.duplicate} duplicates</span><span class="chip gray">${counts.new} new items</span>${vendorReview.errors?.length?`<span class="chip orange">${vendorReview.errors.length} invalid rows</span>`:''}</div>${vendorReview.errors?.length?`<div class="error-list">${vendorReview.errors.slice(0,8).map(esc).join('<br>')}</div>`:''}<div class="table-wrap" style="margin-top:9px"><table><thead><tr><th>Export?</th><th>SKU</th><th>Product</th><th>Current cost</th><th>Supplier cost</th><th>Change</th><th>Unit</th><th>Review flags</th></tr></thead><tbody>${rows.map((r,i)=>`<tr style="${r.duplicate||r.unitMismatch||r.spike?'background:#fff8ed':''}"><td><input type="checkbox" data-vendor-approve="${i}" ${r.approved?'checked':''} ${r.duplicate?'disabled':''} aria-label="Approve ${esc(r.sku)} for export"></td><td><b>${esc(r.sku||'—')}</b></td><td>${esc(r.name||r.product?.name||'New item')}</td><td>${r.product?money(r.product.cost):'—'}</td><td>${Number.isFinite(r.cost)?money(r.cost):'—'}</td><td>${r.product&&Number.isFinite(r.cost)?`${r.delta>=0?'+':''}${r.delta.toFixed(1)}%`:'—'}</td><td>${esc(r.uom||r.product?.uom||'—')}</td><td>${r.duplicate?'<span class="chip orange">Duplicate</span> ':''}${r.isNew?'<span class="chip gray">New SKU</span> ':''}${r.spike?'<span class="chip orange">Cost spike</span> ':''}${r.unitMismatch?'<span class="chip orange">Unit mismatch</span> ':''}${!r.duplicate&&!r.isNew&&!r.spike&&!r.unitMismatch?'<span class="chip success">Looks consistent</span>':''}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No valid cost rows found.</td></tr>'}${missing.map(p=>`<tr style="background:#fff8ed"><td>—</td><td><b>${esc(p.sku)}</b></td><td>${esc(p.name)}</td><td>${money(p.cost)}</td><td>—</td><td>—</td><td>${esc(p.uom||'')}</td><td><span class="chip orange">Possibly discontinued · absent from full catalog file</span></td></tr>`).join('')}</tbody></table></div><div class="small muted" style="margin-top:7px">${rows.filter(r=>r.approved&&!r.duplicate).length} rows approved for export. Export creates a review CSV; it does not change catalog costs.</div>`}
function readVendorFile(file){if(!file)return;if(/\.xlsx?$/i.test(file.name)){vendorReview={file:file.name,supplier:$('vendorSupplier')?.value||'',rows:[],missing:[],errors:['This local MVP reads CSV files. Export the supplier workbook as CSV UTF-8 first.']};render();return}const fr=new FileReader();fr.onload=()=>{try{const {headers,data}=parseCSV(fr.result),skuCol=headerKey(headers,['sku','vendor sku','item number','part number']),costCol=headerKey(headers,['unit cost','cost','new cost','supplier price','price']),nameCol=headerKey(headers,['name','product','description','item name']),uomCol=headerKey(headers,['uom','unit of measure','unit']);if(!skuCol||!costCol)throw Error('Supplier file needs SKU and unit cost columns.');const supplier= $('vendorSupplier')?.value||'',seen=new Set(),errors=[],rows=data.map(r=>{const sku=String(r.values[skuCol]||'').trim(),raw=num(r.values[costCol]),cost=amount(r.values[costCol]),duplicate=!!sku&&seen.has(norm(sku));if(sku)seen.add(norm(sku));const product=model.products.find(p=>norm(p.sku)===norm(sku)),delta=product?.cost&&Number.isFinite(cost)?(cost-product.cost)/product.cost*100:0,unit=String(r.values[uomCol]||'').trim(),unitMismatch=!!(product&&unit&&norm(product.uom)!==norm(unit)),invalid=!sku||!Number.isFinite(cost)||cost<=0;if(invalid)errors.push(`Row ${r.line}: ${!sku?'SKU is blank.':!Number.isFinite(cost)||cost<=0?'unit cost must be a number above $0.':''}`);return{line:r.line,sku,name:nameCol?r.values[nameCol]:'',uom:unit,cost,product,delta,duplicate,isNew:!product,spike:!!product&&delta>=25,unitMismatch,invalid,approved:false}});const dupeCount=new Map();rows.forEach(r=>{const k=norm(r.sku);if(k)dupeCount.set(k,(dupeCount.get(k)||0)+1)});rows.forEach(r=>{if(dupeCount.get(norm(r.sku))>1){r.duplicate=true;r.approved=false}});const full=!!$('vendorFullCatalog')?.checked,missing=full&&supplier?model.products.filter(p=>norm(p.supplier)===norm(supplier)&&!seen.has(norm(p.sku))):[];vendorReview={file:file.name,supplier,fullCatalog:full,rows,missing,errors};render()}catch(e){vendorReview={file:file.name,supplier:$('vendorSupplier')?.value||'',fullCatalog:!!$('vendorFullCatalog')?.checked,rows:[],missing:[],errors:[e.message]};render()}};fr.onerror=()=>{vendorReview={file:file.name,supplier:$('vendorSupplier')?.value||'',rows:[],missing:[],errors:['Could not read this file. Export as UTF-8 CSV and try again.']};render()};fr.readAsText(file)}
function refreshVendorMissing(){if(!vendorReview)return;vendorReview.supplier=$('vendorSupplier')?.value||'';vendorReview.fullCatalog=!!$('vendorFullCatalog')?.checked;const seen=new Set((vendorReview.rows||[]).map(r=>norm(r.sku)));vendorReview.missing=vendorReview.fullCatalog&&vendorReview.supplier?model.products.filter(p=>norm(p.supplier)===norm(vendorReview.supplier)&&!seen.has(norm(p.sku))):[];render()}
function exportVendorApproved(){if(!vendorReview)return;const approved=vendorReview.rows.filter(r=>r.approved&&!r.duplicate&&!r.invalid);if(!approved.length)return toast('Select at least one valid supplier row for export.');const headers=['supplier','sku','product','current_unit_cost_usd','proposed_unit_cost_usd','change_percent','current_uom','supplier_uom','review_flags','buyer_approved'];const csv=[headers,...approved.map(r=>[vendorReview.supplier,r.sku,r.name||r.product?.name||'',r.product?.cost??'',r.cost,r.product?Number(r.delta.toFixed(2)):'',r.product?.uom||'',r.uom||r.product?.uom||'', [r.spike?'cost_spike_25_plus':'',r.unitMismatch?'unit_mismatch':'',r.isNew?'new_sku':''].filter(Boolean).join('|')||'none','yes'])].map(row=>row.map(csvEscape).join(',')).join('\r\n');download('supplier-cost-approved-review.csv',csv);toast(`Exported ${approved.length} approved rows; catalog unchanged.`)}
function productTableHtml(){const rows=model.products.filter(p=>!priceFilter||[p.sku,p.name,p.category,p.supplier].some(v=>norm(v).includes(norm(priceFilter))));const size=50,start=(pricePage-1)*size,slice=rows.slice(start,start+size);return`<div class="table-wrap"><table><thead><tr><th>SKU</th><th>Product</th><th>Category</th><th>Cost</th><th>Base price</th><th>Current margin · trend</th></tr></thead><tbody>${slice.map(p=>{const result=MarginEngine.calculateProductMargin(p),trend=marginTrendHtml('product',p.id);return`<tr><td><b>${esc(p.sku)}</b></td><td>${esc(p.name)}</td><td>${esc(p.category)}</td><td>${money(p.cost)}</td><td>${money(p.listPrice)}</td><td><b>${pct(result.rate)}</b><br>${trend}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No matching products.</td></tr>'}</tbody></table></div><div class="toolbar" style="justify-content:space-between;margin-top:9px"><span class="small muted">Showing ${rows.length?start+1:0}–${Math.min(start+size,rows.length)} of ${rows.length.toLocaleString()} products</span><div><button data-action="price-page" data-delta="-1" ${pricePage<=1?'disabled':''}>Previous</button> <button data-action="price-page" data-delta="1" ${start+size>=rows.length?'disabled':''}>Next</button></div></div>`}
function canUndo(){return(model.priceVersions||[]).some(v=>Array.isArray(v.before))}
function parseCSV(text){const records=[];let row=[],cell='',quoted=false,line=1,start=1;text=String(text||'').replace(/^\uFEFF/,'');const end=()=>{row.push(cell);records.push({cells:row,line:start});row=[];cell=''};for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else{cell+=c;if(c==='\n')line++}}else if(c==='"'){if(cell.trim())throw Error(`Unexpected quote near row ${line}.`);quoted=true}else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){end();if(c==='\r'&&text[i+1]==='\n')i++;line++;start=line}else cell+=c}if(quoted)throw Error('The file has an unfinished quoted value.');if(cell.length||row.length)end();const hs=(records.shift()?.cells||[]).map(x=>x.trim());if(!hs.length||hs.every(x=>!x))throw Error('The CSV needs a header row.');const data=records.filter(r=>r.cells.some(v=>String(v).trim())).map(r=>({line:r.line,values:Object.fromEntries(hs.map((h,i)=>[h,r.cells[i]?.trim()||'']))}));return{headers:hs,data}}
function amount(v){let s=String(v??'').trim();if(!s)return NaN;let neg=/^\(.*\)$/.test(s);s=s.replace(/[(),$\s]/g,'');if(!/^[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?$/.test(s))return NaN;const n=Number(s);return Number.isFinite(n)?(neg?-Math.abs(n):n):NaN}
function headerKey(headers,aliases){return headers.find(h=>aliases.some(a=>norm(h)===norm(a)))||headers.find(h=>aliases.some(a=>norm(h).includes(norm(a))))||''}
function readPriceFile(file){if(!file)return;if(/\.xlsx?$/i.test(file.name)){pricePreview={file:file.name,rows:[],errors:['This local MVP reads CSV files. In Excel, choose File → Save As → CSV UTF-8, then upload again.']};drawPricePreview();return}const fr=new FileReader();fr.onload=()=>{try{const parsed=parseCSV(fr.result),hs=parsed.headers;const sku=headerKey(hs,['sku','item sku','product sku','vendor sku','item number','part number']),price=headerKey(hs,['list price','sell price','price','new price','customer price','unit price']),name=headerKey(hs,['product','description','item name','name']),category=headerKey(hs,['category','product category']),cost=headerKey(hs,['cogs','cost','unit cost','new cost']),uom=headerKey(hs,['uom','unit of measure']);if(!sku||!price)throw Error('We could not find SKU and price columns. Include headers like sku,list_price,name,category,cost.');const seen=new Set(),errors=[],rows=parsed.data.map(r=>{const code=String(r.values[sku]||'').trim(),raw=r.values[price],sell=amount(raw),dupe=seen.has(norm(code));if(code)seen.add(norm(code));const existing=model.products.find(p=>norm(p.sku)===norm(code));const costVal=cost?amount(r.values[cost]):NaN;const row={line:r.line,sku:code,name:name?r.values[name]:'',category:category?r.values[category]:'',uom:uom?r.values[uom]:'',cost:Number.isFinite(costVal)?costVal:undefined,price:sell,before:existing?.listPrice,existing:!!existing,valid:true,error:'',source:r.values};if(!code){row.valid=false;row.error='SKU is blank.'}else if(dupe){row.valid=false;row.error='This SKU appears more than once in the file.'}else if(!Number.isFinite(sell)||sell<=0){row.valid=false;row.error=`Row ${r.line}: price is text or not above $0; expected a number.`}else if(!existing&&(!row.name||!row.category||!Number.isFinite(row.cost))){row.valid=false;row.error='New SKU needs product name, category, and numeric cost.'}if(!row.valid)errors.push(row.error);return row});pricePreview={file:file.name,rows,errors};drawPricePreview()}catch(e){pricePreview={file:file.name,rows:[],errors:[e.message]};drawPricePreview()}};fr.onerror=()=>{pricePreview={file:file.name,rows:[],errors:['Could not read this file. Try exporting it as UTF-8 CSV.']};drawPricePreview()};fr.readAsText(file)}
function drawPricePreview(){const box=$('pricePreview'),errs=$('priceErrors'),commit=$('commitPrices');if(!box)return;if(!pricePreview){box.innerHTML='';errs.innerHTML='';if(commit)commit.disabled=true;return}errs.innerHTML=pricePreview.errors.length?`<div class="error-list"><b>${pricePreview.errors.length} row issue${pricePreview.errors.length===1?'':'s'} to review</b><ul>${pricePreview.errors.slice(0,12).map(e=>`<li>${esc(e)}</li>`).join('')}</ul>${pricePreview.errors.length>12?`<div>and ${pricePreview.errors.length-12} more…</div>`:''}</div>`:`<div class="callout">${esc(pricePreview.file)} · ${pricePreview.rows.length.toLocaleString()} rows read · no validation errors.</div>`;const rows=pricePreview.rows.slice(0,100);box.innerHTML=pricePreview.rows.length?`<div class="card-head" style="margin-top:13px"><h2>Before / after review</h2><span class="small muted">Showing first ${rows.length.toLocaleString()} rows; all valid rows will be included on commit.</span></div><div class="table-wrap"><table><thead><tr><th>Source row</th><th>SKU</th><th>Product</th><th>Before</th><th>After</th><th>Diff</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr style="${r.valid?'':'background:#fff8ed'}"><td>${r.line}</td><td><b>${esc(r.sku)}</b></td><td>${esc(r.name||product(model.products.find(p=>norm(p.sku)===norm(r.sku))?.id)?.name||'')}</td><td>${r.existing?money(r.before):'<span class="muted">New SKU</span>'}</td><td>${Number.isFinite(r.price)?money(r.price):esc(r.source[headerKey(Object.keys(r.source),['price'])]||'')}</td><td>${r.existing&&Number.isFinite(r.price)?money(r.price-r.before):'—'}</td><td><span class="chip ${r.valid?'success':'orange'}">${r.valid?'Ready':esc(r.error)}</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No rows to preview.</div>`;if(commit)commit.disabled=activeRole()==='rep'||!pricePreview.rows.some(r=>r.valid)}
function exportProducts(){const headers=['sku','name','category','supplier','uom','cost','list_price'];const csv=[headers.join(','),...model.products.map(p=>headers.map(k=>csvEscape(k==='list_price'?p.listPrice:p[k])).join(','))].join('\r\n');download('margindesk-price-list.csv',csv,'text/csv')}
function csvEscape(v){let s=String(v??'');if(/^[=+@-]/.test(s.trimStart())&&!/^-\d+(?:\.\d+)?$/.test(s.trim()))s="'"+s;return/[",\r\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s}
function download(name,content,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)}
function commitPrices(){if(activeRole()==='rep'||!pricePreview)return toast('Only managers and analysts can publish list changes.');const valid=pricePreview.rows.filter(r=>r.valid);if(!valid.length)return toast('No valid rows to commit.');const before=clone(model.products),changed=[];valid.forEach(r=>{let p=model.products.find(x=>norm(x.sku)===norm(r.sku));if(!p){p={id:uid('p'),sku:r.sku,name:r.name,category:r.category,supplier:'Imported supplier',uom:r.uom||'EA',cost:r.cost,freight:0,termsCost:0,listPrice:r.price,tiers:{Strategic:r.price*.95,Growth:r.price*.98,Standard:r.price}};model.products.push(p)}else{const old=p.listPrice;p.listPrice=r.price;if(r.cost!==undefined)p.cost=r.cost;p.name=r.name||p.name;p.category=r.category||p.category;p.uom=r.uom||p.uom;Object.keys(p.tiers||{}).forEach(t=>{if(old)p.tiers[t]=Math.round((p.tiers[t]*r.price/old)*100)/100});p.tiers.Standard=r.price}changed.push(p.sku)});model.priceVersions.forEach(v=>delete v.before);model.priceVersions.push({id:uid('pv'),createdAt:new Date().toISOString(),label:`Committed ${pricePreview.file}`,count:changed.length,before,afterCount:model.products.length});if(model.priceVersions.length>12)model.priceVersions=model.priceVersions.slice(-12);save();pricePreview=null;toast(`Published ${changed.length.toLocaleString()} valid price rows.`);render()}
function undoPrice(){const i=[...model.priceVersions].map((v,n)=>({v,n})).reverse().find(x=>Array.isArray(x.v.before));if(!i)return toast('There is no committed price update to undo.');model.products=clone(i.v.before);delete i.v.before;model.priceVersions.push({id:uid('pv'),createdAt:new Date().toISOString(),label:`Undo: ${i.v.label}`,count:model.products.length});save();toast('Latest committed price change was undone.');render()}
function quoteHtml(){const c=customer(quoteDraft.customerId)||model.customers[0];return`${pageHead('Quoting','Build a margin-checked quote quickly. Search products, SKUs, or customer account numbers from the same box.','Field sales workspace')}
<section class="card"><div class="grid-2"><div class="field"><label>Customer</label><select id="quoteCustomer" class="input">${model.customers.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.name)} · ${esc(x.accountNo)} · ${esc(x.tier)}</option>`).join('')}</select></div><div class="field relative"><label>Find a product or account</label><input id="quoteSearch" class="input" placeholder="Try Steel Valve, SV-100, Acme Corp…" autocomplete="off"><div id="quoteSuggestions" class="suggestions"></div></div></div><div class="toolbar" style="margin-top:10px"><span class="chip gray">Account ${esc(c.accountNo)}</span><span class="chip gray">${esc(c.region)} · ${esc(c.tier)}</span><span class="small muted">Quote target: under 60 seconds</span></div></section>
<section class="card"><div class="card-head"><h2>Quote lines</h2><button data-action="add-quote-line">＋ Add product</button></div><div class="quote-lines">${quoteDraft.lines.map((l,i)=>{const p=product(l.productId)||model.products[0];return`<div class="quote-line" data-line="${i}"><div class="field product-cell"><label>Product / SKU</label><select class="input" data-quote-line="${i}" data-field="productId">${model.products.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.sku)} · ${esc(x.name)}</option>`).join('')}</select><small class="muted">${money(tierPrice(p,c))} / ${esc(p.uom)}</small></div><div class="field"><label>Qty</label><input class="input" data-quote-line="${i}" data-field="qty" type="number" min="1" value="${num(l.qty)}"></div><div class="field"><label>Discount %</label><input class="input" data-quote-line="${i}" data-field="discountPct" type="number" min="0" max="100" step="0.1" value="${num(l.discountPct)}"></div><div class="field rebate-field"><label>Rebate %</label><input class="input" data-quote-line="${i}" data-field="rebatePct" type="number" min="0" max="100" step="0.1" value="${num(l.rebatePct)}"></div><div class="field"><label>Accessory $</label><input class="input" data-quote-line="${i}" data-field="accessory" type="number" min="0" step="0.01" value="${num(l.accessory)}"></div><button data-action="remove-line" data-index="${i}" aria-label="Remove quote line" ${quoteDraft.lines.length===1?'disabled':''}>×</button></div>`}).join('')}</div></section>
<section class="card"><div class="card-head"><h2>Live margin thermometer</h2><span id="quoteZone" class="chip gray">Calculating…</span></div><div class="thermometer" role="img" aria-label="Margin guardrail thermometer"><i id="thermoPointer"></i></div><div class="toolbar" id="thermoLabels" style="justify-content:space-between"><span class="small muted">Red &lt; ${policyFor(c,product(quoteDraft.lines[0]?.productId)).walkAway}%</span><span class="small muted">Yellow ${policyFor(c,product(quoteDraft.lines[0]?.productId)).walkAway}% to ${policyFor(c,product(quoteDraft.lines[0]?.productId)).target-1}%</span><span class="small muted">Green ≥ ${policyFor(c,product(quoteDraft.lines[0]?.productId)).target}%</span></div><div id="quoteSummary" class="grid-4" style="margin-top:12px"></div><div id="quoteReason" class="callout" style="margin-top:11px"></div><div class="button-row big" style="margin-top:13px"><button id="createQuote" class="primary">Generate Quote</button><button data-action="quote-preview">Preview quote</button></div><p class="foot">Yellow quotes from a rep go to the manager approval inbox. Red quotes are blocked. This demo keeps quotes and approvals in this browser; it does not contact customers or messaging services.</p></section>
<section class="card"><div class="card-head"><h2>Recent quotes and approvals</h2><span class="small muted">Local workspace only</span></div>${recentQuotesHtml()}</section>`}
function drawQuoteTotals(){if(page!=='quoting')return;const c=customer(quoteDraft.customerId),calc=quoteMath(quoteDraft.lines,c),p=product(quoteDraft.lines[0]?.productId),policy=policyFor(c,p),z=zoneOf(calc.rate,policy),zone=$('quoteZone'),pointer=$('thermoPointer');if(!zone)return;zone.className=`chip ${labelClass(z)}`;zone.textContent=zoneLabel(z,calc.rate,policy);if(pointer)pointer.style.left=`${Math.max(1,Math.min(98,calc.rate/50*100))}%`;const labels=$('thermoLabels');if(labels)labels.innerHTML=`<span class="small muted">Red &lt; ${policy.walkAway}%</span><span class="small muted">Yellow ${policy.walkAway}% to ${policy.target-1}%</span><span class="small muted">Green ≥ ${policy.target}%</span>`;const sum=$('quoteSummary');sum.innerHTML=[['Pocket price',money(calc.pocket)],['Pocket margin',money(calc.margin)],['Margin rate',pct(calc.rate)],['Estimated COGS',money(calc.cogs)]].map(([a,b])=>`<div class="metric"><span>${a}</span><strong>${b}</strong></div>`).join('');const reason=$('quoteReason');if(z==='red')reason.innerHTML=`<b>Quote blocked.</b> ${pct(calc.rate)} is below the ${policy.walkAway}% walk-away rule. Reduce discounts, add eligible items, or ask a manager to review the cost data.`;else if(z==='yellow')reason.innerHTML=`<b>Manager approval required.</b> This quote is ${calc.rate<policy.floor?'also below the manager floor.':''} A manager can approve or deny the request in the inbox.`;else reason.innerHTML=`<b>Ready to generate.</b> Margin is at or above the ${policy.target}% target. Review the customer and line details before sharing.`;const btn=$('createQuote');if(btn){btn.disabled=z==='red';btn.textContent=z==='red'?'Quote blocked':z==='yellow'&&activeRole()==='rep'?'Request Manager Approval':z==='yellow'?'Generate with Manager Override':'Generate Quote';btn.className=z==='red'?'danger':'primary';btn.dataset.zone=z}}
function recentQuotesHtml(){const list=model.quotes.slice().reverse().slice(0,6);return`<div class="table-wrap"><table><thead><tr><th>Quote</th><th>Customer</th><th>Created</th><th>Margin</th><th>Status</th><th></th></tr></thead><tbody>${list.map(q=>{const c=customer(q.customerId),m=quoteMath(q.lines||[{productId:q.productId,qty:q.qty,discountPct:q.discountPct,rebatePct:q.rebatePct||0,accessory:q.accessory||0}],c),z=zoneOf(m.rate,policyFor(c,product(q.productId)));return`<tr><td><b>${esc(q.id)}</b></td><td>${esc(c?.name||'Unknown')}</td><td>${esc(q.createdAt||'')}</td><td><span class="chip ${z==='red'?'red':z==='yellow'?'yellow':''}">${pct(m.rate)}</span></td><td><span class="tag ${q.status==='Pending'?'pending':q.status==='Approved'?'success':q.status==='Denied'?'blocked':''}">${esc(q.status||'Open')}</span></td><td><button data-quote="${esc(q.id)}">Open</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No quotes yet.</td></tr>'}</tbody></table></div>`}
function addQuoteProduct(id){if(id){quoteDraft.lines.push({productId:id,qty:1,discountPct:0,rebatePct:0,accessory:0})}else quoteDraft.lines.push({productId:model.products[0]?.id,qty:1,discountPct:0,rebatePct:0,accessory:0});render()}
function createQuote(){const c=customer(quoteDraft.customerId),math=quoteMath(quoteDraft.lines,c),p=product(quoteDraft.lines[0]?.productId),policy=policyFor(c,p),z=zoneOf(math.rate,policy);if(z==='red')return toast('This quote is below the walk-away margin and cannot be created.');const id='QT-'+String(Math.max(200,...model.quotes.map(q=>Number(String(q.id).replace(/\D/g,''))||0))+1),snapshot={id,customerId:c.id,lines:clone(quoteDraft.lines),status:z==='yellow'&&activeRole()==='rep'?'Pending':'Approved',createdAt:new Date().toISOString().slice(0,10),marginRate:math.rate,margin:math.margin,pocket:math.pocket,createdBy:activeRole()};model.quotes.push(snapshot);if(snapshot.status==='Pending')model.approvals.push({id:uid('ap'),quoteId:id,status:'Pending',requestedBy:model.users.find(u=>u.role===activeRole())?.name||'Sales rep',requestedByRole:activeRole(),createdAt:new Date().toISOString(),quote:clone(snapshot)});save();if(snapshot.status==='Pending'){toast(`Manager approval requested for ${id}.`);render();return}toast(`Quote ${id} created.`);quoteDraft={customerId:c.id,lines:[{productId:model.products[0].id,qty:1,discountPct:0,rebatePct:0,accessory:0}]};render();openQuote(id)}
function openQuote(id){const q=model.quotes.find(x=>x.id===id);if(!q)return;const c=customer(q.customerId),lines=q.lines||[{productId:q.productId,qty:q.qty,discountPct:q.discountPct,rebatePct:q.rebatePct||0,accessory:q.accessory||0}],calc=quoteMath(lines,c);showModal(`<div class="card-head"><h2>Quote ${esc(q.id)}</h2><span class="tag ${q.status==='Pending'?'pending':q.status==='Approved'?'success':'blocked'}">${esc(q.status)}</span></div><p>${esc(c?.name||'Customer')} · ${esc(c?.accountNo||'')}</p><div class="table-wrap" style="margin:12px 0"><table><thead><tr><th>Product</th><th>Qty</th><th>Item list</th><th>Discount</th><th>Rebate</th><th>Accessory</th><th>Freight</th><th>Terms</th><th>Pocket</th><th>Margin</th></tr></thead><tbody>${calc.lines.map((line,i)=>{const input=lines[i];return`<tr><td>${esc(line.product?.name||input.productId)}</td><td>${line.qty}</td><td>${money(line.baseList)}</td><td>−${money(line.discount)}</td><td>−${money(line.rebate)}</td><td>${money(line.accessory)}</td><td>−${money(line.freight)}</td><td>−${money(line.terms)}</td><td>${money(line.pocket)}</td><td>${money(line.margin)}</td></tr>`}).join('')}</tbody></table></div><div class="grid-3">${metric('Pocket price',money(calc.pocket))}${metric('Pocket margin',money(calc.margin))}${metric('Margin rate',pct(calc.rate))}</div><div class="callout" style="margin-top:12px">${q.signature?'<b>Signed on screen.</b> Signature saved locally with this quote.':'Quote remains in this browser. Customer communication is prepared by the user.'}</div><h3 style="font-size:14px;margin:16px 0 8px">Finish quote</h3><div class="button-row big"><button class="primary" data-quote-action="sms" data-id="${esc(q.id)}">Send Web Link via SMS</button><button data-quote-action="email" data-id="${esc(q.id)}">Email PDF</button><button data-quote-action="sign" data-id="${esc(q.id)}">Sign on Screen Now</button></div><p class="foot">SMS/email open a draft for you to review. A hosted secure customer link is not active in this local prototype.</p><div class="modal-foot"><button data-close>Close</button></div>`)}
function quoteAction(action,id){const q=model.quotes.find(x=>x.id===id);if(!q)return;const c=customer(q.customerId),calc=quoteMath(q.lines||[],c);if(action==='sms'){const smsBody=encodeURIComponent(`Quote ${q.id} for ${c?.name||'you'}: ${money(calc.pocket)} estimated pocket price, valid for review. Reply to this message to request the hosted quote link.`);showModal(`<h2>Prepare SMS draft</h2><p>The hosted customer link is not active in this prototype. This opens a text draft with quote details; review it before sending.</p><div class="result">Quote ${esc(q.id)} · ${esc(c?.name||'')} · ${money(calc.pocket)}</div><div class="modal-foot"><button data-close>Cancel</button><a class="button primary" style="text-decoration:none" href="sms:${encodeURIComponent(c?.phone||'')}?body=${smsBody}">Open SMS draft</a></div>`)}else if(action==='email'){showModal(`<h2>Prepare customer PDF</h2><p>Save the quote as PDF, then attach it to your email. The mail app will open a draft; this prototype cannot attach or send files itself.</p><div class="result"><b>${esc(q.id)} · ${esc(c?.name||'')}</b><br>Total ${money(calc.pocket)} · Margin ${pct(calc.rate)}</div><div class="modal-foot"><button data-close>Close</button><button data-print="${esc(q.id)}">Print / Save PDF</button><a class="button" style="text-decoration:none" href="mailto:${encodeURIComponent(c?.email||'')}?subject=${encodeURIComponent('Quote '+q.id+' from Northwind Industrial Supply')}&body=${encodeURIComponent(`Hello,\n\nPlease find quote ${q.id} for ${c?.name||''}. Total: ${money(calc.pocket)}. I will attach the PDF after saving it from the print dialog.\n\nRegards`) }">Open email draft</a></div>`)}else if(action==='sign'){showModal(`<h2>Sign quote ${esc(q.id)}</h2><p class="muted small">Draw with a finger or mouse. Signature will be saved locally with this quote.</p><canvas class="signature" id="signaturePad"></canvas><div class="modal-foot"><button data-action="clear-sign">Clear</button><button data-close>Cancel</button><button class="primary" data-save-sign="${esc(q.id)}">Save signature</button></div>`);initSignature()}}
function initSignature(){const c=$('signaturePad');if(!c)return;const ctx=c.getContext('2d'),rect=c.getBoundingClientRect(),scale=window.devicePixelRatio||1;c.width=rect.width*scale;c.height=180*scale;ctx.scale(scale,scale);ctx.lineWidth=2.3;ctx.lineCap='round';ctx.strokeStyle='#163447';let drawing=false;const pos=e=>{const r=c.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};c.onpointerdown=e=>{drawing=true;c.setPointerCapture(e.pointerId);const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y)};c.onpointermove=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke()};c.onpointerup=()=>drawing=false;c.onpointercancel=()=>drawing=false}
function saveSignature(id){const c=$('signaturePad');if(!c)return;const q=model.quotes.find(x=>x.id===id);if(!q)return;q.signature=c.toDataURL('image/png');q.signedAt=new Date().toISOString();q.status='Signed';save();closeModal();toast(`Signature saved on ${id}.`);render()}
function quotePreviewHtml(){const c=customer(quoteDraft.customerId),calc=quoteMath(quoteDraft.lines,c);return`<h2>Quote preview</h2><p>${esc(c?.name||'Customer')} · ${esc(c?.accountNo||'')}</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Item list</th><th>Discount</th><th>Rebate</th><th>Accessory</th><th>Freight</th><th>Terms</th><th>Pocket</th><th>Margin</th></tr></thead><tbody>${calc.lines.map((line,i)=>{const input=quoteDraft.lines[i];return`<tr><td>${esc(line.product?.sku)} · ${esc(line.product?.name)}</td><td>${line.qty}</td><td>${money(line.baseList)}</td><td>−${money(line.discount)}</td><td>−${money(line.rebate)}</td><td>${money(line.accessory)}</td><td>−${money(line.freight)}</td><td>−${money(line.terms)}</td><td>${money(line.pocket)}</td><td>${money(line.margin)}</td></tr>`}).join('')}</tbody></table></div><div class="result">Pocket ${money(calc.pocket)} · Margin ${money(calc.margin)} · ${pct(calc.rate)}</div><div class="modal-foot"><button data-close>Close</button></div>`}function printQuote(id){const q=model.quotes.find(x=>x.id===id),c=customer(q?.customerId);if(!q)return;const inputs=q.lines||[{productId:q.productId,qty:q.qty,discountPct:q.discountPct,rebatePct:q.rebatePct||0,accessory:q.accessory||0}],m=quoteMath(inputs,c),rows=m.lines.map(line=>`<tr><td>${esc(line.product?.sku)} · ${esc(line.product?.name)}</td><td>${line.qty}</td><td>${money(line.baseList)}</td><td>−${money(line.discount)}</td><td>−${money(line.rebate)}</td><td>${money(line.accessory)}</td><td>−${money(line.freight)}</td><td>−${money(line.terms)}</td><td>${money(line.pocket)}</td><td>${money(line.margin)}</td></tr>`).join('');const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print this quote.');return}w.document.write(`<!doctype html><html><head><title>${esc(q.id)}</title><style>body{font:15px Arial;padding:40px;color:#1c2b34}h1{color:#163447}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}@media print{button{display:none}}</style></head><body><h1>Northwind Industrial Supply</h1><h2>Quote ${esc(q.id)}</h2><p>Prepared for ${esc(c?.name||'')} · ${esc(c?.accountNo||'')} · ${esc(q.createdAt)}</p><table><thead><tr><th>Item</th><th>Qty</th><th>Item list</th><th>Discount</th><th>Rebate</th><th>Accessory</th><th>Freight</th><th>Terms</th><th>Pocket</th><th>Margin</th></tr></thead><tbody>${rows}</tbody></table><h2>Pocket ${money(m.pocket)} · Margin ${money(m.margin)} (${pct(m.rate)})</h2><p>Quote generated in MarginDesk local MVP. Confirm commercial terms before sending.</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function rebateProgress(a){const spend=num(a.eligibleSpend),amount=spend>=num(a.threshold)?spend*num(a.rate)/100:0,remaining=Math.max(0,num(a.nextTier||a.threshold)-spend),progress=a.nextTier?Math.min(100,spend/num(a.nextTier)*100):Math.min(100,spend/num(a.threshold)*100);return{spend,amount,remaining,progress}}
function rebatesHtml(){const vendors=model.rebates.filter(a=>a.kind==='Vendor'),customers=model.rebates.filter(a=>a.kind==='Customer');return`${pageHead('Rebates','Track buyer-approved customer incentives and supplier rebate credits, with period totals and source rows for human review.','Manager and analyst workspace')}
<section class="card"><div class="card-head"><div><h2>Agreements</h2><div class="small muted">Flat rate after the threshold applies to the full eligible spend. Confirm written terms before relying on any estimate.</div></div><button class="primary" data-action="add-rebate">＋ Add agreement</button></div><div class="grid-2">${model.rebates.map(a=>{const x=rebateProgress(a),party=a.kind==='Customer'?customer(a.partyId)?.name:a.partyId;return`<div class="rebat-card"><div class="toolbar" style="justify-content:space-between"><span class="chip ${a.kind==='Vendor'?'gray':'success'}">${esc(a.kind)} program</span><span class="small muted">${esc(a.periodStart)} → ${esc(a.periodEnd)}</span></div><h3 style="margin-top:9px">${esc(a.name)}</h3><div class="small muted">${esc(party||a.partyId)} · ${esc(a.eligibleSkus.join(', '))}</div><div class="toolbar" style="justify-content:space-between;margin:11px 0 6px"><span>${money(x.spend)} eligible</span><span>${money(x.remaining)} to next tier</span></div><div class="progress"><i style="width:${x.progress}%"></i></div><div class="grid-3" style="margin-top:10px"><div><small class="muted">Rate</small><br><b>${a.rate}%</b></div><div><small class="muted">Threshold</small><br><b>${money(a.threshold)}</b></div><div><small class="muted">Modeled value</small><br><b>${money(x.amount)}</b></div></div>${a.kind==='Customer'&&x.remaining>0?`<div class="approval-card"><b>Sales nudge:</b> ${esc(party)} is ${money(x.remaining)} away from its ${a.nextRate||a.rate}% buying tier. <button data-remind="${esc(a.id)}">Prepare reminder</button></div>`:''}</div>`}).join('')}</div></section>
<section class="card"><div class="card-head"><div><h2>Supplier rebate capture audit</h2><div class="small muted">Compare modeled amount with supplier credits; candidate shortfall is for review only.</div></div><select class="input" id="auditAgreement">${vendors.map(a=>`<option value="${esc(a.id)}">${esc(a.partyId)} · ${esc(a.name)}</option>`).join('')}</select></div><div id="rebateAudit"></div><div class="callout" style="margin-top:11px">This prototype does not interpret contracts, prepare claims, or post receivables. The buyer confirms eligibility and every source row.</div></section>
<section class="card"><div class="card-head"><h2>Supplier credit records</h2><span class="small muted">Seeded remittance rows · local only</span></div><div class="table-wrap"><table><thead><tr><th>Credit ID</th><th>Supplier</th><th>Date</th><th>Amount</th><th>Reference</th></tr></thead><tbody>${(model.supplierCredits||[]).map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.vendor)}</td><td>${esc(c.date)}</td><td>${money(c.amount)}</td><td>${esc(c.reference)}</td></tr>`).join('')}</tbody></table></div></section>`}
function drawRebateAudit(){const box=$('rebateAudit'),sel=$('auditAgreement');if(!box||!sel)return;const a=model.rebates.find(x=>x.id===sel.value)||model.rebates.find(x=>x.kind==='Vendor');if(!a){box.innerHTML='<div class="empty">Add a vendor agreement to run a capture review.</div>';return}const x=rebateProgress(a),credits=(model.supplierCredits||[]).filter(c=>norm(c.vendor)===norm(a.partyId)&&c.date>=a.periodStart&&c.date<=a.periodEnd).reduce((s,c)=>s+num(c.amount),0),expected=x.amount,gap=Math.max(0,expected-credits),rows=model.invoices.filter(inv=>{const p=product(inv.productId);return p&&(a.kind==='Vendor'?norm(p.supplier)===norm(a.partyId):inv.customerId===a.partyId)&&inv.date>=a.periodStart&&inv.date<=a.periodEnd&&(!a.eligibleSkus.length||a.eligibleSkus.includes(p.sku))});box.innerHTML=`<div class="grid-4">${metric('Eligible spend',money(x.spend))}${metric('Modeled rebate',money(expected))}${metric('Recorded credits',money(credits))}${metric('Possible shortfall',money(gap))}</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Source row</th><th>Party / SKU</th><th>Date</th><th>Amount</th><th>Review</th></tr></thead><tbody>${rows.map(inv=>{const p=product(inv.productId),c=customer(inv.customerId);return`<tr><td>${esc(inv.id)}</td><td>${esc(c?.name||a.partyId)} · ${esc(p?.sku||'')}</td><td>${esc(inv.date)}</td><td>${money(inv.netSales)}</td><td><span class="chip gray">Confirm eligibility</span></td></tr>`}).join('')}${(model.supplierCredits||[]).filter(c=>norm(c.vendor)===norm(a.partyId)&&c.date>=a.periodStart&&c.date<=a.periodEnd).map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.vendor)} · credit</td><td>${esc(c.date)}</td><td>−${money(c.amount)}</td><td><span class="chip gray">Recorded credit</span></td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:10px"><span class="chip ${gap>0?'orange':'success'}">${gap>0?'Possible difference for human review':'No modeled difference'}</span><span class="small muted">${rows.length} eligible invoice rows · ${model.supplierCredits.filter(c=>norm(c.vendor)===norm(a.partyId)).length} credit rows across all periods</span><button data-action="export-rebate-audit">Download source-linked review CSV</button></div>`}
function addRebateModal(){showModal(`<h2>Add rebate agreement</h2><p class="muted small">Enter terms confirmed by your program owner. This does not interpret contracts.</p><div class="grid-2"><div class="field"><label>Agreement type</label><select class="input" id="newRebateKind"><option>Vendor</option><option>Customer</option></select></div><div class="field"><label>Party</label><select class="input" id="newRebateParty"></select></div><div class="field"><label>Agreement name</label><input id="newRebateName" class="input" placeholder="e.g. Annual growth incentive"></div><div class="field"><label>Flat rate (%)</label><input id="newRebateRate" class="input" type="number" value="2" min="0" step="0.1"></div><div class="field"><label>Threshold ($)</label><input id="newRebateThreshold" class="input" type="number" value="20000" min="0"></div><div class="field"><label>Eligible SKU list</label><input id="newRebateSkus" class="input" placeholder="SV-100, SV-200"></div><div class="field"><label>Period start</label><input id="newRebateStart" class="input" type="date" value="2026-01-01"></div><div class="field"><label>Period end</label><input id="newRebateEnd" class="input" type="date" value="2026-12-31"></div></div><div class="modal-foot"><button data-close>Cancel</button><button class="primary" data-action="save-rebate">Save agreement</button></div>`);drawPartyOptions()}
function drawPartyOptions(){const kind=$('newRebateKind')?.value,field=$('newRebateParty');if(!field)return;field.innerHTML=(kind==='Vendor'?Array.from(new Set(model.products.map(p=>p.supplier))).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`):model.customers.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`)).join('')}
function saveRebate(){const kind=$('newRebateKind').value,partyId=$('newRebateParty').value,rate=num($('newRebateRate').value),threshold=num($('newRebateThreshold').value),skus=$('newRebateSkus').value.split(',').map(s=>s.trim()).filter(Boolean),start=$('newRebateStart').value,end=$('newRebateEnd').value;if(!partyId||!rate||!threshold||!start||!end||start>end)return toast('Enter a party, positive rate and threshold, and valid period.');const agreement={id:uid('ra'),kind,partyId,name:$('newRebateName').value.trim()||`${partyId} rebate`,rate,threshold,periodStart:start,periodEnd:end,eligibleSkus:skus,eligibleSpend:sumInvoiceSpend(kind,partyId,start,end,skus),credits:0,nextTier:threshold,nextRate:rate};model.rebates.push(agreement);save();closeModal();toast('Rebate agreement saved locally.');render()}
function sumInvoiceSpend(kind,partyId,start,end,skus){return model.invoices.filter(i=>{const p=product(i.productId);return p&&i.date>=start&&i.date<=end&&(kind==='Vendor'?norm(p.supplier)===norm(partyId):i.customerId===partyId)&&(!skus.length||skus.includes(p.sku))}).reduce((s,i)=>s+num(i.netSales),0)}
function connectorsHtml(){return`${pageHead('Data connectors','Start with sample records or import a local invoice CSV. Live ERP, CRM, and messaging connections are not enabled.','Integration setup')}
<section class="card"><div class="card-head"><h2>Connector catalog</h2><span class="chip yellow">Phase 2 · not connected</span></div><div class="grid-3">${[['HubSpot','Customer and account mapping','CRM read / write sync'],['NetSuite','Invoices, products, costs and customers','Read-only import first'],['QuickBooks Enterprise','Invoices and accounting exports','No journal posting'],['Slack','Manager approval notices','User-authorized workspace'],['Microsoft Teams','Approval requests','User-authorized workspace'],['Excel / CSV','Spreadsheet workflows','CSV import/export active']].map(([a,b,c],i)=>`<div class="connector"><h3>${a}</h3><p>${b}</p><span class="chip ${i===5?'success':'gray'}">${i===5?'CSV available':'Connector interface only'}</span><div style="margin-top:9px"><button data-connect="${esc(a)}">${i===5?'Import / export':'View setup'}</button></div><div class="small muted" style="margin-top:6px">${c}</div></div>`).join('')}</div><div class="callout" style="margin-top:12px">No customer credentials are requested or stored. A real integration needs OAuth, tenant isolation, least-privilege scopes, retention rules, and buyer-specific tests.</div></section>
<section class="card"><div class="card-head"><h2>Import historic transactions</h2><span class="small muted">CSV fallback · local processing</span></div><p class="small muted">Expected headers: customer (name or account no), sku, qty, net_sales, date. Imported rows update local rebate progress and source references.</p><div class="dropzone" id="invoiceDrop"><b>Choose an invoice CSV</b><input id="invoiceFile" type="file" accept=".csv,text/csv" style="display:block;margin:10px auto 0"></div><div id="invoiceImportResult" class="small muted" style="margin-top:9px"></div><div class="toolbar" style="margin-top:10px"><button data-action="download-invoice-sample">Download sample invoice CSV</button><span class="chip gray">${model.invoices.length} invoice lines currently loaded</span></div></section>
<section class="card"><div class="card-head"><h2>Seeded demo workspace</h2><span class="chip success">Ready to explore</span></div><p class="small muted">${model.customers.length} customers · ${model.products.length} products · ${model.orders.length} orders · ${model.rebates.length} agreements · ${model.quotes.length} quotes.</p><div class="row-actions"><button data-action="export-prototype">Export this browser data as JSON</button><button data-action="reset-demo">Reset local demo data</button></div><p class="small muted">Use this JSON in the hosted app’s Data migration &amp; export page. Review the file before importing.</p></section>`}
function connectorCardsSmall(){return[['HubSpot','Not connected'],['NetSuite','Not connected'],['QuickBooks Enterprise','Not connected']].map(([name,status])=>`<div class="connector"><b>${name}</b><div class="small muted">${status} · CSV fallback ready</div></div>`).join('')}
function renderSidebar(){const aside=$('inflationPanel'),wasMobile=aside.classList.contains('show-mobile');aside.classList.toggle('collapsed',collapsed);aside.classList.remove('show-mobile');aside.innerHTML=`<button class="side-toggle" data-action="toggle-sidebar"><span>Inflation pass-through</span><span>${collapsed?'›':'−'}</span></button><div class="side-content"><div class="card" style="margin-top:10px"><div class="card-head"><h2>Quick adjustment</h2><span class="chip gray">Preview</span></div><div class="field"><label>Product category</label><select id="inflationCategory" class="input">${[...new Set(model.products.map(p=>p.category))].map(c=>`<option ${c===inflationDraft.category?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field" style="margin-top:10px"><label>Input a cost change, e.g. Steel +6%</label><input id="inflationText" class="input" value="${esc(inflationDraft.text)}" placeholder="Steel +6%"></div><div class="field" style="margin-top:10px"><label>Cost increase <b id="inflationLabel">${inflationDraft.change}%</b></label><input type="range" min="-20" max="30" value="${inflationDraft.change}" id="inflationSlider"></div><div id="inflationPreview" class="small" style="margin-top:10px"></div><button class="primary" style="width:100%;margin-top:10px" data-action="publish-inflation" ${activeRole()==='rep'?'disabled':''}>Publish adjustment</button><div class="toolbar" style="margin-top:8px"><button data-action="undo-price" ${canUndo()?'':'disabled'}>Undo</button><button data-action="open-prices">History</button></div><p class="foot">Publishes locally to base and tier prices. Confirm every preview before using real customer prices.</p></div></div>`;if(!collapsed)drawInflationPreview();if(wasMobile&&window.matchMedia('(max-width: 780px)').matches)aside.classList.add('show-mobile')}
function parseInflation(){const raw=$('inflationText')?.value||'',m=raw.match(/(-?\d+(?:\.\d+)?)\s*%/);return m?Number(m[1]):num($('inflationSlider')?.value)}
function selectedInflationCategory(){return $('inflationCategory')?.value||inflationDraft.category||'Steel Valves'}
function passThroughPrice(p,oldPrice,change,oldCost=p.cost){return MarginEngine.calculatePassThrough(p,oldPrice,change,oldCost).newPrice}
function drawInflationPreview(){const box=$('inflationPreview');if(!box)return;const cat=selectedInflationCategory(),change=parseInflation(),rows=model.products.filter(p=>p.category===cat).map(p=>({p,oldCost:p.cost,newCost:p.cost*(1+change/100),old:p.listPrice,next:passThroughPrice(p,p.listPrice,change),tiers:Object.entries(p.tiers||{}).map(([tier,price])=>({tier,old:price,next:passThroughPrice(p,price,change)}))}));$('inflationLabel').textContent=`${change}%`;box.innerHTML=`<div class="toolbar" style="justify-content:space-between;margin-bottom:5px"><b>${esc(cat)}</b><span>${rows.length} SKUs</span></div>${rows.slice(0,6).map(x=>`<div class="version-row"><span>${esc(x.p.sku)}<div class="small muted">Cost ${money(x.oldCost)} → ${money(x.newCost)}</div></span><span>${money(x.old)} → <b>${money(x.next)}</b><span class="trend ${change>=0?'up':'down'}">${change>=0?'↑':'↓'} ${change}% cost</span><div class="small muted">${x.tiers.map(t=>`${esc(t.tier)} ${money(t.old)}→${money(t.next)}`).join(' · ')}</div></span></div>`).join('')}${rows.length>6?`<div class="small muted">and ${rows.length-6} more SKUs</div>`:''}${rows.length?`<div class="small muted" style="margin-top:5px">Preview holds each SKU/tier's current margin while cost changes.</div>`:'<div class="empty">No products in this category.</div>'}`}
function publishInflation(){if(activeRole()==='rep')return toast('Only a manager or analyst can publish a price change.');const category=selectedInflationCategory(),change=parseInflation(),targets=model.products.filter(p=>p.category===category);if(!targets.length||!Number.isFinite(change)||change<=-100)return toast('Choose a valid category and adjustment.');const before=clone(model.products);targets.forEach(p=>{const oldCost=p.cost,oldList=p.listPrice,oldTiers={...(p.tiers||{})};p.listPrice=Math.round(passThroughPrice(p,oldList,change,oldCost)*100)/100;p.tiers=Object.fromEntries(Object.entries(oldTiers).map(([t,price])=>[t,Math.round(passThroughPrice(p,price,change,oldCost)*100)/100]));p.cost=Math.round(oldCost*(1+change/100)*100)/100});model.priceVersions.forEach(v=>delete v.before);model.priceVersions.push({id:uid('pv'),createdAt:new Date().toISOString(),label:`${category} costs ${change>=0?'+':''}${change}%`,count:targets.length,before,afterCount:model.products.length});save();toast(`Published the ${change}% cost pass-through to ${targets.length} ${category} SKUs. Undo is available.`);render()}
function saveAgreementReminder(id){const a=model.rebates.find(x=>x.id===id);if(!a)return;const c=customer(a.partyId),name=a.kind==='Customer'?c?.name||a.partyId:a.partyId,x=rebateProgress(a);const message=`Reminder draft: ${name} is ${money(x.remaining)} away from the next ${a.nextRate||a.rate}% rebate tier. Confirm eligible SKUs, timing, and margin before recommending an order.`;navigator.clipboard?.writeText(message).catch(()=>{});showModal(`<h2>Sales reminder draft</h2><p class="muted">Review the customer's current need and margin before sending a nudge.</p><div class="result">${esc(message)}</div><div class="modal-foot"><button data-close>Close</button><button data-action="copy-reminder" data-text="${esc(message)}">Copy reminder</button></div>`)}
function exportRebateAudit(){const sel=$('auditAgreement'),a=model.rebates.find(x=>x.id===sel?.value);if(!a)return;const x=rebateProgress(a),credits=model.supplierCredits.filter(c=>norm(c.vendor)===norm(a.partyId)&&c.date>=a.periodStart&&c.date<=a.periodEnd).reduce((s,c)=>s+num(c.amount),0),headers=['record_type','source_id','date','party','sku','amount_usd','eligible_spend_usd','modeled_rebate_usd','recorded_credits_usd','possible_difference_usd','review_note'],rows=[];rows.push(['period_summary','','',a.partyId,'', '',x.spend,x.amount,credits,Math.max(0,x.amount-credits),'Buyer must confirm written rule and eligibility']);model.invoices.filter(i=>{const p=product(i.productId);return p&&(a.kind==='Vendor'?norm(p.supplier)===norm(a.partyId):i.customerId===a.partyId)&&i.date>=a.periodStart&&i.date<=a.periodEnd&&(!a.eligibleSkus.length||a.eligibleSkus.includes(p.sku))}).forEach(i=>{const p=product(i.productId);rows.push(['invoice',i.id,i.date,a.partyId,p.sku,i.netSales,'','','','', 'Confirm eligible source row'])});model.supplierCredits.filter(c=>norm(c.vendor)===norm(a.partyId)&&c.date>=a.periodStart&&c.date<=a.periodEnd).forEach(c=>rows.push(['supplier_credit',c.id,c.date,c.vendor,'',-Math.abs(c.amount),'','','','', 'Confirm this credit belongs to this program']));download('rebate-source-review.csv',[headers,...rows].map(r=>r.map(csvEscape).join(',')).join('\r\n'))}
function orderModal(id){const o=allOrders().find(x=>x.order.id===id);if(!o)return toast('Order detail was not found.');const tag=o.margin<0?'blocked':'success';showModal(`<div class="card-head"><h2>${esc(o.order.id)} · ${esc(o.c.name)}</h2><span class="tag ${tag}">${o.margin<0?'Loss-making':'Positive margin'}</span></div><p class="muted">${esc(o.p.sku)} · ${esc(o.p.name)} · ${o.qty} units · ${esc(o.c.region)}</p><div class="table-wrap" style="margin:12px 0"><table><tbody><tr><th>List price</th><td>${money(o.list)}</td></tr><tr><th>Discount</th><td>−${money(o.discount)} (${o.order.discountPct}%)</td></tr><tr><th>Off-invoice rebate</th><td>−${money(o.rebate)} (${o.order.offInvoiceRebatePct}%)</td></tr><tr><th>Freight</th><td>−${money(o.freight)}</td></tr><tr><th>Payment terms cost</th><td>−${money(o.terms)}</td></tr><tr><th>Pocket price</th><td><b>${money(o.pocket)}</b></td></tr><tr><th>Cost of goods</th><td>−${money(o.cogs)}</td></tr><tr><th>Pocket margin</th><td><b>${money(o.margin)} · ${pct(o.rate)}</b></td></tr></tbody></table></div>${o.margin<0?`<div class="approval-card"><b>Margin turned negative.</b> Without freight the order would contribute ${money(o.marginWithoutFreight)}. Freight and discount terms are the primary leak drivers. Discount ${o.order.discountApproved===false?'is not approved':'approval status is unknown'}.</div>`:''}<div class="modal-foot"><button data-close>Close</button><button data-action="quote-customer" data-customer="${esc(o.c.id)}">Build a quote for this customer</button></div>`)}
function profitabilityMatrix(){const list=allOrders(),groupsByCustomer=new Map();list.forEach(order=>{const group=groupsByCustomer.get(order.c.id)||{c:order.c,rows:[]};group.rows.push(order);groupsByCustomer.set(order.c.id,group)});const arr=[...groupsByCustomer.values()].map(group=>{const totals=MarginEngine.aggregate(group.rows);return{c:group.c,sales:totals.pocket,rate:totals.rate}}),avgSales=arr.reduce((sum,x)=>sum+x.sales,0)/(arr.length||1),avgMargin=arr.reduce((sum,x)=>sum+x.rate,0)/(arr.length||1);const groups=[['High volume · high margin',[]],['High volume · low margin',[]],['Low volume · high margin',[]],['Low volume · low margin',[]]];arr.forEach(x=>{const hi=x.sales>=avgSales,prof=x.rate>=avgMargin;groups[hi?(prof?0:1):(prof?2:3)][1].push(x)});showModal(`<h2>Customer profitability matrix</h2><p class="muted small">Seeded order data · volume split at average sales ${money(avgSales)}; profitability split at ${pct(avgMargin)}.</p><div class="matrix">${groups.map(([name,items])=>`<div class="quad"><b>${name}</b>${items.length?items.map(x=>`<div class="small" style="margin-top:5px">${esc(x.c.name)} · ${money(x.sales)} · ${pct(x.rate)}</div>`).join(''):'<div class="small muted">No customers in this group</div>'}</div>`).join('')}</div><div class="modal-foot"><button data-close>Close</button></div>`)}
function parseDate(s){s=String(s||'').trim();if(/^\d{4}-\d\d-\d\d$/.test(s))return s;const m=s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);if(!m)return'';return`${m[3]}-${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}`}
function importInvoiceFile(file){if(!file)return;const fr=new FileReader();fr.onload=()=>{try{const {headers,data}=parseCSV(fr.result),customerCol=headerKey(headers,['customer','customer name','account','account no','account number']),skuCol=headerKey(headers,['sku','product sku','item','item number']),qtyCol=headerKey(headers,['qty','quantity']),salesCol=headerKey(headers,['net sales','net_sales','sales','amount','invoice total']),dateCol=headerKey(headers,['date','invoice date']);if(!customerCol||!skuCol||!salesCol)throw Error('Expected customer, sku, net_sales, and date columns.');const out=[],errors=[];data.forEach(r=>{const name=r.values[customerCol],sku=r.values[skuCol],c=model.customers.find(x=>norm(x.name)===norm(name)||norm(x.accountNo)===norm(name)),p=model.products.find(x=>norm(x.sku)===norm(sku)),sale=amount(r.values[salesCol]),date=parseDate(r.values[dateCol]);if(!c||!p||!Number.isFinite(sale)||!date){errors.push(`Row ${r.line}: ${!c?'customer not matched':!p?'SKU not matched':!Number.isFinite(sale)?'net sales must be numeric':'date is invalid'}.`);return}out.push({id:`IMP-${Date.now().toString(36)}-${r.line}`,customerId:c.id,productId:p.id,qty:qtyCol?num(r.values[qtyCol]):1,netSales:sale,date})});model.invoices=[...model.invoices,...out];model.rebates.forEach(a=>{if(out.length)a.eligibleSpend=sumInvoiceSpend(a.kind,a.partyId,a.periodStart,a.periodEnd,a.eligibleSkus)});save();const box=$('invoiceImportResult');if(box)box.innerHTML=`<span class="chip success">${out.length} rows imported</span> ${errors.length?`<span class="chip orange">${errors.length} rows skipped</span><div class="error-list">${errors.slice(0,8).map(esc).join('<br>')}</div>`:'All rows matched.'}`;toast(`Imported ${out.length} invoice rows locally.`);if(page==='rebates')render()}catch(e){const box=$('invoiceImportResult');if(box)box.innerHTML=`<span class="chip orange">${esc(e.message)}</span>`}};fr.readAsText(file)}
function globalMatches(query){const q=norm(query);if(!q)return[];const cs=model.customers.filter(c=>[c.name,c.accountNo,c.region,c.tier].some(x=>norm(x).includes(q))).slice(0,5).map(c=>({type:'Customer',id:c.id,label:c.name,meta:`${c.accountNo} · ${c.tier}`})),ps=model.products.filter(p=>[p.sku,p.name,p.category,p.supplier].some(x=>norm(x).includes(q))).slice(0,7).map(p=>({type:'Product',id:p.id,label:p.name,meta:`${p.sku} · ${p.category}`}));return[...cs,...ps].slice(0,9)}
function drawGlobalSearch(){const input=$('globalSearch'),box=$('globalResults'),items=globalMatches(input.value);if(!items.length){box.classList.remove('show');box.innerHTML='';return}box.innerHTML=items.map(x=>`<div class="search-result" data-search-pick="${esc(x.type)}" data-id="${esc(x.id)}"><span><b>${esc(x.label)}</b><small class="muted" style="display:block">${esc(x.meta)}</small></span><span class="chip gray">${x.type}</span></div>`).join('');box.classList.add('show')}
function openProfile(id){const c=customer(id);if(!c)return;const rel=model.rebates.filter(a=>a.kind==='Customer'&&a.partyId===id),recent=allOrders().filter(o=>o.c.id===id),totals=MarginEngine.aggregate(recent);showModal(`<div class="card-head"><h2>${esc(c.name)}</h2><span class="chip gray">${esc(c.accountNo)} · ${esc(c.tier)}</span></div><p class="muted">${esc(c.region)} · ${esc(c.email)}</p><div class="grid-3" style="margin-top:12px">${metric('Orders in sample',recent.length)}${metric('Margin this sample',pct(totals.rate))}${metric('Rebate programs',rel.length)}</div>${rel.map(a=>{const p=rebateProgress(a);return`<div class="approval-card">${esc(a.name)} · ${money(p.remaining)} to next tier</div>`}).join('')}<div class="modal-foot"><button data-close>Close</button><button class="primary" data-action="quote-customer" data-customer="${esc(id)}">Build quote</button></div>`)}
function policyInput(e){const k=e.target.dataset.policy;if(!k)return;let v=Number(e.target.value),m=scopedPolicy();if(k==='target'){m.target=Math.max(v,m.floor+1);e.target.value=m.target}else if(k==='floor'){m.floor=Math.min(m.target-1,Math.max(m.walkAway,v));e.target.value=m.floor}else{m.walkAway=Math.min(m.floor,Math.max(5,v));e.target.value=m.walkAway}const lab=$(`policy-${k}-label`);if(lab)lab.textContent=m[k]+'%';const panels=[...document.querySelectorAll('.zone-preview')];panels.forEach(p=>{p.innerHTML=`<div class="green-zone"><b>GREEN · AUTO APPROVED</b><br>≥ ${m.target}%</div><div class="yellow-zone"><b>YELLOW · MANAGER APPROVAL</b><br>${m.walkAway}% to ${m.target-1}%</div><div class="red-zone"><b>RED · HARD LOCK</b><br>&lt; ${m.walkAway}%</div>`});const preview=$('openQuotePreview');if(preview){const open=model.quotes.filter(q=>q.status==='Open'),z=open.map(q=>{const c=customer(q.customerId),p=product(q.productId),m=quoteMath(q.lines||[{productId:q.productId,qty:q.qty,discountPct:q.discountPct,rebatePct:q.rebatePct||0,accessory:q.accessory||0}],c);return zoneOf(m.rate,policyFor(c,p))});preview.textContent=`Live preview · ${open.length} open quotes: ${z.filter(x=>x==='green').length} Green · ${z.filter(x=>x==='yellow').length} Yellow · ${z.filter(x=>x==='red').length} Red. Counts update when the rules change.`}save()}
function setQuoteCustomer(id){if(!customer(id))return;quoteDraft.customerId=id;render()}
function saveQuoteInput(el){if(el.id==='quoteCustomer'){quoteDraft.customerId=el.value;render();return}if(el.dataset.quoteLine!==undefined){const i=Number(el.dataset.quoteLine),f=el.dataset.field;if(!quoteDraft.lines[i])return;quoteDraft.lines[i][f]=f==='productId'?el.value:num(el.value);drawQuoteTotals()}}
function saveApproval(id,decision){const a=model.approvals.find(x=>x.id===id);if(!a||a.status!=='Pending')return;const q=model.quotes.find(x=>x.id===a.quoteId);a.status=decision;a.decidedAt=new Date().toISOString();a.decidedBy=model.users.find(u=>u.role===activeRole())?.name||'Manager';if(q)q.status=decision;save();toast(`${a.quoteId} ${decision.toLowerCase()}.`);render()}
function handleAction(action,el){switch(action){case'export-prototype':download('margindesk-prototype-export.json',JSON.stringify({model},null,2),'application/json');toast('Downloaded prototype data JSON. Review before importing.');break;case'choose-price':$('priceFile')?.click();break;case'choose-vendor-file':$('vendorFile')?.click();break;case'export-vendor-approved':exportVendorApproved();break;case'download-vendor-sample':download('supplier-cost-review-sample.csv','sku,name,uom,unit_cost\r\nSV-100,Steel Gate Valve,EA,96.20\r\nSV-200,Steel Ball Valve,BOX,119.00\r\nSV-999,New Steel Fitting,EA,42.50\r\nSV-999,Duplicate row,EA,41.50');break;case'clear-vendor-review':vendorReview=null;render();break;case'commit-prices':commitPrices();break;case'export-prices':exportProducts();break;case'sync-prices':$('priceFile')?.click();break;case'undo-price':undoPrice();break;case'price-page':pricePage=Math.max(1,pricePage+Number(el.dataset.delta));const table=$('productTable');if(table)table.innerHTML=productTableHtml();break;case'add-quote-line':addQuoteProduct();break;case'remove-line':quoteDraft.lines.splice(Number(el.dataset.index),1);render();break;case'quote-preview':showModal(quotePreviewHtml());break;case'fix-now':{const urgent=allOrders().find(o=>o.margin<0);if(urgent?.order?.id)orderModal(urgent.order.id);else setPage('prices');break}case'matrix':profitabilityMatrix();break;case'connectors':page='connectors';render();break;case'open-prices':setPage('prices');break;case'toggle-sidebar':if(window.matchMedia('(max-width: 780px)').matches){$('inflationPanel').classList.remove('show-mobile')}else{collapsed=!collapsed;localStorage.setItem('md-sidebar-collapsed',collapsed?'1':'0');renderSidebar()}break;case'show-inflation':$('inflationPanel').classList.toggle('show-mobile');collapsed=false;renderSidebar();$('inflationPanel').classList.add('show-mobile');break;case'publish-inflation':publishInflation();break;case'add-rebate':addRebateModal();break;case'save-rebate':saveRebate();break;case'export-rebate-audit':exportRebateAudit();break;case'copy-reminder':navigator.clipboard?.writeText(el.dataset.text||'').then(()=>toast('Reminder copied.')).catch(()=>toast('Select and copy the reminder text.'));break;case'download-invoice-sample':{const sample='customer,sku,qty,net_sales,date\nAC-104,SV-100,10,1190,2026-10-02\nBR-220,HV-300,4,888,2026-10-05\nVI-041,EL-405,20,820,2026-10-08';download('margindesk-invoice-sample.csv',sample);break}case'reset-demo':model=clone(seed);pricePreview=null;vendorReview=null;save();toast('Demo workspace reset.');render();break;case'quote-customer':{const id=el.dataset.customer;closeModal();quoteDraft.customerId=id;quoteDraft.lines=[{productId:model.products[0].id,qty:1,discountPct:0,rebatePct:0,accessory:0}];setPage('quoting');break}case'clear-sign':initSignature();break}}
root.addEventListener('click',e=>{const btn=e.target.closest('button,[data-order],[data-water],[data-quote],[data-search-pick],[data-approval],[data-remind],[data-search-customer]');if(!btn)return;if(btn.dataset.page){setPage(btn.dataset.page);return}if(btn.dataset.action){handleAction(btn.dataset.action,btn);return}if(btn.dataset.water){showModal(orderDetailHtml(btn.dataset.water));return}if(btn.dataset.order){orderModal(btn.dataset.order);return}if(btn.dataset.searchCustomer){openProfile(btn.dataset.searchCustomer);return}if(btn.dataset.quote){openQuote(btn.dataset.quote);return}if(btn.dataset.approval){saveApproval(btn.dataset.approval,btn.dataset.decision);return}if(btn.dataset.remind){saveAgreementReminder(btn.dataset.remind);return}if(btn.dataset.searchPick){pickSearch(btn.dataset.searchPick,btn.dataset.id);return}if(btn.id==='createQuote'){createQuote();return}if(btn.dataset.connect){connectClick(btn.dataset.connect);return}if(btn.dataset.back){setPage(btn.dataset.back);return}});
root.addEventListener('input',e=>{const t=e.target;if(t.dataset.policy){policyInput(e);return}if(t.dataset.quoteLine!==undefined){saveQuoteInput(t);return}if(t.id==='priceFilter'){priceFilter=t.value;pricePage=1;const table=$('productTable');if(table)table.innerHTML=productTableHtml();return}if(t.id==='quoteSearch'){drawQuoteSuggestions(t.value);return}});
root.addEventListener('change',e=>{const t=e.target;if(t.id==='priceFile'&&t.files?.[0]){readPriceFile(t.files[0]);return}if(t.id==='vendorFile'&&t.files?.[0]){readVendorFile(t.files[0]);return}if(t.id==='vendorSupplier'||t.id==='vendorFullCatalog'){refreshVendorMissing();return}if(t.dataset.vendorApprove!==undefined){const row=vendorReview?.rows?.[Number(t.dataset.vendorApprove)];if(row&&!row.duplicate&&!row.invalid){row.approved=t.checked;render()}return}if(t.id==='quoteCustomer'){saveQuoteInput(t);return}if(t.dataset.quoteLine!==undefined){saveQuoteInput(t);return}if(t.id==='policyScope'){policyScope=t.value;render();return}if(t.id==='auditAgreement'){drawRebateAudit();return}if(t.id==='invoiceFile'&&t.files?.[0]){importInvoiceFile(t.files[0]);return}});
root.addEventListener('dragover',e=>{const zone=e.target.closest('#priceDrop,#vendorDrop');if(zone){e.preventDefault();zone.classList.add('drag')}});root.addEventListener('dragleave',e=>{const zone=e.target.closest('#priceDrop,#vendorDrop');if(zone)zone.classList.remove('drag')});root.addEventListener('drop',e=>{if(e.target.closest('#priceDrop')){e.preventDefault();$('priceDrop')?.classList.remove('drag');readPriceFile(e.dataTransfer.files?.[0])}if(e.target.closest('#vendorDrop')){e.preventDefault();$('vendorDrop')?.classList.remove('drag');readVendorFile(e.dataTransfer.files?.[0])}});
function drawQuoteSuggestions(q){const box=$('quoteSuggestions');if(!box)return;const items=globalMatches(q);if(!items.length){box.classList.remove('show');box.innerHTML='';return}box.innerHTML=items.map(x=>`<div class="suggestion" data-qpick="${esc(x.type)}" data-id="${esc(x.id)}"><b>${esc(x.label)}</b><div class="small muted">${esc(x.meta)} · ${x.type}</div></div>`).join('');box.classList.add('show')}
function pickSearch(type,id){$('globalResults').classList.remove('show');$('globalSearch').value='';if(type==='Customer'){openProfile(id)}else{quoteDraft.lines.push({productId:id,qty:1,discountPct:0,rebatePct:0,accessory:0});setPage('quoting')}}
function connectClick(name){if(name==='Excel / CSV'){setPage('prices');return}showModal(`<h2>${esc(name)} connector</h2><p>This connector is represented in the setup catalog only. No credentials are collected and no live connection is active.</p><div class="callout">Phase 2 setup will need an authorized connection, minimum permissions, mapped fields, a test tenant, and buyer approval before any data is synchronized.</div><div class="modal-foot"><button data-close>Close</button></div>`)}
$('globalSearch').addEventListener('input',drawGlobalSearch);$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Escape')$('globalResults').classList.remove('show');if(e.key==='Enter'){const first=globalMatches(e.target.value)[0];if(first)pickSearch(first.type,first.id)}});document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))$('globalResults').classList.remove('show');if(e.target.closest('[data-close]'))closeModal();const item=e.target.closest('[data-qpick]');if(item){const type=item.dataset.qpick,id=item.dataset.id;$('quoteSearch').value='';$('quoteSuggestions').classList.remove('show');if(type==='Customer'){quoteDraft.customerId=id;render()}else addQuoteProduct(id)}const pick=e.target.closest('[data-search-pick]');if(pick){pickSearch(pick.dataset.searchPick,pick.dataset.id)}const qa=e.target.closest('[data-quote-action]');if(qa)quoteAction(qa.dataset.quoteAction,qa.dataset.id);const pr=e.target.closest('[data-print]');if(pr)printQuote(pr.dataset.print);const sign=e.target.closest('[data-save-sign]');if(sign)saveSignature(sign.dataset.saveSign);const connect=e.target.closest('[data-connect]');if(connect)connectClick(connect.dataset.connect);const kind=e.target.closest('#newRebateKind');if(kind)drawPartyOptions()});
$('inflationPanel').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action,b)});$('inflationPanel').addEventListener('input',e=>{if(e.target.id==='inflationSlider'){inflationDraft.change=num(e.target.value);inflationDraft.text=`${selectedInflationCategory()} ${inflationDraft.change>=0?'+':''}${inflationDraft.change}%`;if($('inflationText'))$('inflationText').value=inflationDraft.text;drawInflationPreview()}else if(e.target.id==='inflationText'){const m=e.target.value.match(/(-?\d+(?:\.\d+)?)\s*%/);if(m){inflationDraft.change=Number(m[1]);if($('inflationSlider'))$('inflationSlider').value=Math.max(-20,Math.min(30,Number(m[1])))}inflationDraft.text=e.target.value;const l=norm(e.target.value),guess=l.includes('steel')?'Steel Valves':l.includes('aluminum')?'Aluminum Parts':l.includes('hvac')?'HVAC Supplies':l.includes('electrical')?'Electrical Supplies':'';if(guess){inflationDraft.category=guess;if($('inflationCategory'))$('inflationCategory').value=guess}drawInflationPreview()}});$('inflationPanel').addEventListener('change',e=>{if(e.target.id==='inflationCategory'){inflationDraft.category=e.target.value;inflationDraft.text=`${e.target.value} ${inflationDraft.change>=0?'+':''}${inflationDraft.change}%`;if($('inflationText'))$('inflationText').value=inflationDraft.text;drawInflationPreview()}});document.addEventListener('click',e=>{const open=e.target.closest('[data-action="show-inflation"]');if(open)handleAction('show-inflation',open)});document.addEventListener('change',e=>{if(e.target.id==='newRebateKind')drawPartyOptions()});
$('modal').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action,b)});$('modal').addEventListener('click',e=>{if(e.target.closest('[data-save-sign]'))saveSignature(e.target.closest('[data-save-sign]').dataset.saveSign)});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{model={...model,...JSON.parse(e.newValue)};render();toast('Workspace updated in another tab.')}catch(_){}}});
document.querySelectorAll('.bottom-nav [data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
render();if(page==='rebates')drawRebateAudit();
})();

